const now = new Date();
const results = [];

for (const item of $input.all()) {
  const row = item.json;
  const status = (row['Status'] || '').toString();

  // Skip anyone already booked
  if (status.includes('Booked')) continue;

  const receivedAt = new Date(row['Received At']);
  if (isNaN(receivedAt.getTime())) continue;

  const daysElapsed = Math.floor((now - receivedAt) / (1000 * 60 * 60 * 24));

  let stage = null;
  if (daysElapsed >= 10 && !status.includes('Day10')) stage = 'day10';
  else if (daysElapsed >= 5 && !status.includes('Day5')) stage = 'day5';
  else if (daysElapsed >= 2 && !status.includes('Day2')) stage = 'day2';

  if (stage) {
    results.push({ json: { ...row, stage, daysElapsed } });
  }
}

return results;
